                                      pkinit_plg_crypto_context plg_cryptoctx,
                                      pkinit_req_crypto_context req_cryptoctx,
                                      pkinit_identity_crypto_context id_cryptoctx,
                                      unsigned char *pdid_buf,
                                      unsigned int pdid_len,
                                      int *valid_kdcPkId) {
    krb5_error_code ret = 0;
    krb5_data *pdid_data = NULL;
    pkinit_kdc_pk_id_t kdc_pk_id = NULL;
    krb5_principal kdc_princ;
    krb5_principal kdc_cert_issuer = NULL;
    krb5_cert_info cert_info = NULL;
    krb5_cert_get_key_info_context key_info = NULL;
    int match = 0;

    *valid_kdcPkId = 0;

    pdid_data = data_alloc(pdid_buf, pdid_len);
    if (!pdid_data) {
        ret = KRB5KDC_ERR_PREAUTH_FAILED;
        goto cleanup;
    }

    ret = pkinit_unwrap_pkid(context, pdid_data, &kdc_pk_id);
    if (ret) {
        goto cleanup;
    }

    kdc_princ = context->kdc_krbtgt_princ;

    ret = krb5_build_principal_simple(context, &kdc_cert_issuer,
                                      strlen("KDC-ISSUER"), "KDC-ISSUER");
    if (ret) {
        goto cleanup;
    }

    ret = plg_cryptoctx->cert_get_key_info(plg_cryptoctx->keyblock, kdc_princ,
                                           kdc_cert_issuer, 0, &key_info);
    if (ret) {
        goto cleanup;
    }

    ret = plg_cryptoctx->cert_get_key_info_data(key_info, &cert_info);
    if (ret) {
        goto cleanup;
    }

    if (cert_info->keyid_len != kdc_pk_id->keyid_len ||
        memcmp(cert_info->keyid_val, kdc_pk_id->keyid_val,
               cert_info->keyid_len) != 0) {
        ret = KRB5KDC_ERR_PREAUTH_FAILED;
        goto cleanup;
    }

    *valid_kdcPkId = 1;

cleanup:
    if (cert_info)
        krb5_free_cert_info(context, cert_info);
    if (key_info)
        plg_cryptoctx->cert_free_key_info(key_info);
    if (kdc_cert_issuer)
        krb5_free_principal(context, kdc_cert_issuer);
    if (kdc_pk_id)
        pkinit_free_kdc_pk_id(kdc_pk_id);
    if (pdid_data)
        data_free(pdid_data);

    return ret;
}

