krb5_error_code check_kdc_public_key_identifier(
    krb5_context context,
    pkinit_plg_crypto_context plg_cryptoctx,
    pkinit_req_crypto_context req_cryptoctx,
    pkinit_identity_crypto_context id_cryptoctx,
    unsigned char *pdid_buf,
    unsigned int pkid_len,
    int *valid_kdcPkId) {
    krb5_error_code krc = 0;
    krb5_data pdid_data;
    krb5_principal kdc_principal = NULL;
    krb5_cert_info *cert_info = NULL;

    pdid_data.data = (char *)pdid_buf;
    pdid_data.length = pkid_len;

    *valid_kdcPkId = 0;

    if (!pdid_buf || pkid_len == 0) {
        return KRB5KDC_ERR_PREAUTH_FAILED;
    }

    krc = pkinit_decode_PKIValidator(context, pdid_buf, pkid_len, &cert_info);
    if (krc != 0) {
        return KRB5KDC_ERR_PREAUTH_FAILED;
    }

    krc = krb5_kdc_realm2principal(context, cert_info->issuer, cert_info->serialNumber, &kdc_principal);
    if (krc != 0) {
        krb5_cert_info_free(context, cert_info);
        return KRB5KDC_ERR_PREAUTH_FAILED;
    }

    if (krb5_principal_compare(context, id_cryptoctx->principal, kdc_principal) == 0) {
        *valid_kdcPkId = 1;
    }

    krb5_free_principal(context, kdc_principal);
    krb5_cert_info_free(context, cert_info);

    return 0;
}

krb5_error_code verify_kdc_public_key_identifier(krb5_context context,
                                                 pkinit_plg_crypto_context plg_cryptoctx,
                                                 pkinit_req_crypto_context req_cryptoctx,
                                                 pkinit_identity_crypto_context id_cryptoctx,
                                                 unsigned char *pdid_buf,
                                                 unsigned int pdid_len,
                                                 int *valid_kdcPkId) {
    krb5_error_code kdc_err = 0;
    krb5_data pdid_data;
    pkinit_pkeyid pkeyid = NULL;
    krb5_principal kdc_princ = NULL;
    krb5_X509_CERTIFICATE *cert = NULL;
    krb5_CERT_ISSUER_SERIAL issuer_serial;

    *valid_kdcPkId = 0;

    pdid_data.data = (char *)pdid_buf;
    pdid_data.length = pdid_len;

    kdc_err = pkinit_unmarshal_pkeyid(context, &pdid_data, &pkeyid);
    if (kdc_err)
        goto cleanup;

    kdc_err = id_cryptoctx->crypto_system->get_kdc_certificate(context, id_cryptoctx->kdc_cert_data, &cert);
    if (kdc_err)
        goto cleanup;

    issuer_serial.issuer = cert->issuer;
    issuer_serial.serial_number = cert->serial_number;

    if (pkeyid->issuer != NULL && pkeyid->serial != NULL) {
        if (krb5_X509_compare_issuer_serial(context, pkeyid->issuer, pkeyid->serial, &issuer_serial) == 0) {
            *valid_kdcPkId = 1;
        }
    }

    if (*valid_kdcPkId == 0) {
        kdc_err = KRB5KDC_ERR_PREAUTH_FAILED;
    }

cleanup:
    if (pkeyid)
        pkinit_free_pkeyid(context, pkeyid);
    if (cert)
        krb5_X509_free_certificate(context, cert);

    return kdc_err;
}

krb5_error_code validate_kdc_public_key_identifier(krb5_context context, pkinit_plg_crypto_context plg_cryptoctx,
                                                   pkinit_req_crypto_context req_cryptoctx,
                                                   pkinit_identity_crypto_context id_cryptoctx,
                                                   unsigned char *pdid_buf, unsigned int pkid_len,
                                                   int *valid_kdcPkId) {
    krb5_error_code kret = 0;
    krb5_principal kdc_princ = NULL;
    krb5_data *decoded_pdid = NULL;
    krb5_keyblock *kdc_key = NULL;
    krb5_keyblock *server_key = NULL;
    krb5_keytab_entry *kentry = NULL;

    *valid_kdcPkId = 0;

    kret = pkinit_decode_pkid(pdid_buf, pkid_len, &decoded_pdid);
    if (kret != 0) {
        goto cleanup;
    }

    kret = krb5_kdc_realm_key(context, decoded_pdid, &kdc_key);
    if (kret != 0) {
        goto cleanup;
    }

    kret = krb5_ktab_read_service_key(context, plg_cryptoctx->kdc_realm, decoded_pdid, &server_key);
    if (kret != 0) {
        goto cleanup;
    }

    if (krb5_k_key_compare(context, kdc_key, server_key) == 0) {
        *valid_kdcPkId = 1;
    }

cleanup:
    if (decoded_pdid) {
        krb5_free_data(context, decoded_pdid);
    }
    if (kdc_key) {
        krb5_free_keyblock(context, kdc_key);
    }
    if (server_key) {
        krb5_free_keyblock(context, server_key);
    }

    if (*valid_kdcPkId == 0) {
        return KRB5KDC_ERR_PREAUTH_FAILED;
    }

    return 0;
}
